#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in the log, plus every catalog SKU (SKU-9) even if it had no
# movements that day.
{
    awk '
        BEGIN { net["SKU-9"] += 0 }
        { net[$1] += ($2 == "receipt" ? $3 : -$3) }
        END { for (sku in net) print sku, net[sku] }' movements.log | sort
} > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in the log, plus every catalog SKU (SKU-9) even if it had no
# movements that day.
{
    awk '
        BEGIN { net["SKU-9"] += 0 }
        { net[$1] += ($2 == "receipt" ? $3 : -$3) }
        END { for (sku in net) print sku, net[sku] }' movements.log 2>/dev/null
} > stock.txt || true

# Guarantee the catalog SKU is always present, per the reporting rules.
grep -q '^SKU-9 ' stock.txt || echo "SKU-9 0" >> stock.txt
sort -o stock.txt stock.txt
